def compute(vars):
    value = max(vars["v1"], vars["v2"])
    return {
        "value": value,
        "trace": {
            "2011_value": vars["v1"],
            "2012_value": vars["v2"],
            "maximum": value,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }
